SELECT COUNT(*) FROM sys_dict_data WHERE deleted = 0

    AND dict_type = #{dictType}


    AND dict_label LIKE CONCAT('%', #{dictLabel}, '%')


    AND status = #{status}

SELECT id, dict_type, dict_label, dict_value, dict_sort, remark, status, create_time
FROM sys_dict_data WHERE deleted = 0

    AND dict_type = #{dictType}


    AND dict_label LIKE CONCAT('%', #{dictLabel}, '%')


    AND status = #{status}

ORDER BY dict_sort ASC, create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

